100	func literalNewStats() TimeStats {
101		return TimeStats{
102			Buckets: []TimeBucket{
103				{Start: 0, End: 10, TxCount: 4, DistinctTxIDs: 3, Blocks: 3},
104				{Start: 10, End: 20, TxCount: 3, DistinctTxIDs: 2, Blocks: 1},
105				{Start: 20, End: 30, TxCount: 0, DistinctTxIDs: 0, Blocks: 0},
106			},
