281	// chain so the guarantees do not hide inside a DeepEqual.
282	func TestReorgTimeStatsCountingSemanticsOnBothChains(t *testing.T) {
283		old := literalOldStats()
284		if old.Buckets[0].TxCount != 3 || old.Buckets[0].DistinctTxIDs != 2 {
