341		// After the reorg returns, only the complete new-chain answer is allowed.
342		after, err := index.QueryTimeStats(reorgStatsQuery)
343		if err != nil {
344			t.Fatal(err)
345		}
346		if !reflect.DeepEqual(after, literalNewStats()) {
347			t.Fatalf("post-reorg query not wholly on the new chain:\n%+v", after)
348		}
349		if after.ToHeight != 4 {
350			t.Fatalf("upper height must follow the shortened tip, got %d", after.ToHeight)
351		}
352		if after.Buckets[2].TxCount != 0 || after.MissingTimeBlocks != 0 {
353			t.Fatalf("removed height 5 tx f or old missing count leaked: %+v", after)
354		}
