446	// A query issued while a successful reorg is committed but has not yet
447	// returned (new chain installed under the lock) must wait and then observe
448	// the complete NEW chain, including the shortened upper height.
449	func TestQueryTimeStatsInFlightObservesCompleteNewChain(t *testing.T) {
450		index := buildOldChain(t)
451		h := installReorgStatsHooks(t)
452		oldRef, newRef := literalOldStats(), literalNewStats()
453	
454		reorgErr := make(chan error, 1)
455		go func() {
456			_, err := index.Reorg(reorgNewBranch())
457			reorgErr <- err
458		}()
459		<-h.reorgParked // new branch applied (tip 4), Reorg still holds the lock
460	
461		result := make(chan TimeStats, 1)
462		go func() {
463			stats, err := index.QueryTimeStats(reorgStatsQuery)
464			if err != nil {
465				t.Errorf("query during reorg failed: %v", err)
466				return
467			}
468			result <- stats
469		}()
470	
471		// Releasing the reorg lets it return and hands the lock to the waiting
472		// query; the chain the query can first see is already entirely the new one.
473		close(h.releaseReorg)
474		if err := <-reorgErr; err != nil {
475			t.Fatalf("reorg failed: %v", err)
476		}
477		close(h.releaseQuery) // no query parks in this timing, but keep the seam drained
478	
479		got := <-result
480		if err := classifyTimeStats(got, oldRef, newRef); err != nil {
481			t.Fatalf("query across reorg commit did not return one complete chain:\n%v", err)
482		}
483		if !reflect.DeepEqual(got, newRef) {
484			t.Fatalf("query after reorg commit must see the complete new chain:\n%+v", got)
485		}
486	}
