231	// gateWriteOutcome is what a blockingGateWriter returns from its one blocked
232	// Write call.
233	type gateWriteOutcome struct {
234		accepted int
235		err      error
236	}
237	
238	// blockingGateWriter silently accepts up to prefix bytes of the first write,
239	// records them, signals entered, and then blocks until the test releases it
240	// with a fixed return value. Export performs exactly one Write, which is all
241	// this writer needs to support.
242	type blockingGateWriter struct {
243		prefix   int
244		entered  chan struct{}
245		release  chan gateWriteOutcome
246		received bytes.Buffer
247	}
248	
249	func (w *blockingGateWriter) Write(p []byte) (int, error) {
250		n := w.prefix
251		if n > len(p) {
252			n = len(p)
253		}
254		w.received.Write(p[:n])
255		close(w.entered)
256		out := <-w.release
257		if out.accepted > len(p) {
258			out.accepted = len(p)
259		}
260		return out.accepted, out.err
261	}
