// classifyTxPage accepts got only when its visible contents are byte-for-byte
// the first-page answer of exactly one chain. The opaque NextCursor is not
// part of this view; callers validate it by following it. It deliberately
// does NOT treat "hit count equals TotalMatches" as sufficient: an ordered,
// correctly counted stitched page still carries records from both branches.
func classifyTxPage(got, oldRef, newRef TxPage) error {
	type view struct {
		Hits          []TxHit
		TotalMatches  int64
		MatchedBlocks int64
		ToHeight      int64
	}
	of := func(p TxPage) view {
		return view{Hits: p.Hits, TotalMatches: p.TotalMatches, MatchedBlocks: p.MatchedBlocks, ToHeight: p.ToHeight}
	}
	g, o, n := of(got), of(oldRef), of(newRef)
	if reflect.DeepEqual(g, o) || reflect.DeepEqual(g, n) {
		return nil
	}

